// One-off golden capture, run in a detached worktree at the stack base.
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { it } from "vitest";
import { canonicalJson } from "../src/content-ir/canonical.js";
import { createChangeSource, parseChangeSourceSelector } from "../src/inputs/change-source.js";
import { resolveLocalChangeSource } from "../src/inputs/change-source-local.js";
import { digestChangeSourceProducerScope } from "../src/inputs/change-source-acquisition.js";
import { buildGoldenRepository, fixtureGit } from "./support/change-source-fixture.js";

const IDENTITY = { kind: "local-checkout" as const, identitySha256: "0".repeat(63) + "1" };
const CASES = { "two-dot": "main..feature", "three-dot": "main...feature", "root-single-commit": "root" };

it("captures the golden change-source records", async () => {
  const root = await mkdtemp(join(tmpdir(), "docsfab-golden-"));
  try {
    const repository = await buildGoldenRepository(root);
    const workspaceRevision = await fixtureGit(repository, ["rev-parse", "feature"]);
    const cases: Record<string, { manifest: string; producerScopeSha256: string }> = {};
    for (const [name, value] of Object.entries(CASES)) {
      const resolved = await resolveLocalChangeSource({
        sourcePath: repository,
        selector: parseChangeSourceSelector(value),
        workspaceRevision,
      });
      const { schemaVersion, kind, changeSourceSha256, ...body } = resolved.changeSource;
      void schemaVersion; void kind; void changeSourceSha256;
      const resealed = createChangeSource({
        ...body,
        revision: { ...body.revision, repository: IDENTITY },
      });
      cases[name] = {
        manifest: `${JSON.stringify(JSON.parse(canonicalJson(resealed)), null, 2)}\n`,
        producerScopeSha256: digestChangeSourceProducerScope({ changeSource: resealed, readScope: ["."] }),
      };
    }
    await writeFile(process.env.GOLDEN_OUT!, `${JSON.stringify(cases, null, 2)}\n`);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}, 120_000);
